--
-- Generated by scripts/gen-institution-seeds.mjs from data/institutions/gb.csv.
-- Do not hand-edit: change the CSV (or curate.py) and regenerate before the apply; an applied
-- file is never edited. Ids are UUIDv5 of 'GB|<source_key>' (see the generator).
--
-- Sources:
--   https://register-api.officeforstudents.org.uk/api/Download/ (OfS Register, file 2026-10-02)
--   https://register-api.officeforstudents.org.uk/api/Provider (OfS, registered, no university title)
--   https://www.medr.cymru/wp-content/uploads/2026/07/Register-Medr-31Jul2026-English.xlsx
--   https://www.sfc.ac.uk/our-funding/university-funding/
--   https://www.nidirect.gov.uk/articles/universities-and-colleges-northern-ireland
--
-- is_active = false: nothing here is visible until the activation migration runs (module
-- go-live SOP). sort_order 500: below every TRNC row, above Other (999).
--
-- RE-RUN: ON CONFLICT (id) DO NOTHING, so a later edit to one of these rows is never
-- reverted. The checks below assert the ids exist in GB, not their current values.
--
-- EXECUTION: supabase-migrate workflow (dry, then -f apply=true). Requires 20261095.

SET ROLE postgres;

BEGIN;

DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'institutions_country_name_unique'
                  AND conrelid = 'public.institutions'::regclass) THEN
    RAISE EXCEPTION 'REFUSING: 20261095 (institutions.country, per-country names) is not applied. Nothing applied.';
  END IF;
END $$;

